source:
source note sys.dataset(fields: [title, subtitle, status, as_of, metric1_label, metric1_value, metric2_label, metric2_value, summary])

copy app { class: vocabulary, en: "Mail" }
copy gist { class: model-copy, en: "Simulation only: no real package, no live tracking, nothing to confirm." }

view root Surface(pad: .tight) {
  Col(gap: 8) {
    Row(gap: 8, align: .center) {
      Icon(name: .mail, size: .row)
      TextCaption(text: copy.app, width: .fill)
      TextCaption(text: "Simulation", width: .fit)
    }
    TextTitle(text: note.title, width: .fill)
    TextBody(text: note.subtitle, width: .fill)
    TextBody(text: note.status, width: .fill)
    TextBody(text: note.summary, width: .fill)
    TextCaption(text: note.metric1_label, width: .label)
    TextCaption(text: note.metric1_value, width: .fill)
    TextCaption(text: note.metric2_label, width: .label)
    TextCaption(text: note.metric2_value, width: .fill)
    TextBody(text: copy.gist, width: .fill)
  }
}
